foreach (['trackers' => 'tracker', 'fls' => 'fls', 'cameras' => 'camera'] as $list => $key) foreach ($inventory[$list] as $item) if ((string)($item['id'] ?? '') === (string)($device[$key . '_product_id'] ?? '')) $inventoryIdentifiers[$key] = (string)($item['imei'] ?? '');
