<div class="col-md-6"><label class="form-label" for="package-type">Package</label><select class="form-select" name="package_type" id="package-type" required><?php foreach ($packageTypes as $type): ?><option value="<?= $esc($type) ?>" <?= $package === $type ? 'selected' : '' ?>><?= $esc($type) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6" id="tracker-product-field"><label class="form-label" for="tracker-product">Tracker from inventory</label><select class="form-select" name="tracker_product_id" id="tracker-product" <?= $cameraOnly ? 'disabled' : 'required' ?>><option value="">Choose tracker</option><?php foreach ($inventory['trackers'] as $product): ?><option value="<?= (int)$product['id'] ?>" data-identifier="<?= $esc($product['imei'] ?? '') ?>" <?= (string)($device['tracker_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?><?= !empty($product['imei']) ? ' · ' . $esc($product['imei']) : '' ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select></div>
<div class="col-md-6" id="tracker-identifier-field"><label class="form-label" for="tracker-identifier">Tracker IMEI / serial</label><input class="form-control" id="tracker-identifier" name="tracker_identifier" inputmode="numeric" pattern="[0-9]+" maxlength="100" value="<?= $esc($trackerIdentifierValue) ?>" <?= $trackerIdentifierReadonly ? 'readonly' : '' ?> <?= $cameraOnly ? 'disabled' : 'required' ?>><div class="form-text">Auto-filled for individually serialized trackers. For bulk stock, enter the IMEI / serial of the tracker being installed.</div></div>
<div class="col-md-6 d-none" id="fls-field"><label class="form-label" for="fls-product">FLS from inventory</label><select class="form-select" name="fls_product_id" id="fls-product" <?= $needsFls ? 'required' : 'disabled' ?>><option value="">Choose FLS</option><?php foreach ($inventory['fls'] as $product): ?><option value="<?= (int)$product['id'] ?>" data-identifier="<?= $esc($product['imei'] ?? '') ?>" <?= (string)($device['fls_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · <?= $esc($product['imei'] ?? '') ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select><input class="form-control mt-2" id="fls-identifier" value="<?= $esc($inventoryIdentifiers['fls']) ?>" placeholder="FLS serial from inventory" readonly><?php if (!$inventory['fls']): ?><div class="form-text">No serialized FLS units in stock.</div><?php endif; ?></div>
<div class="col-md-6 d-none" id="camera-field"><label class="form-label" for="camera-product">Camera from inventory</label><select class="form-select" name="camera_product_id" id="camera-product" <?= $needsCamera ? 'required' : 'disabled' ?>><option value="">Choose camera</option><?php foreach ($inventory['cameras'] as $product): ?><option value="<?= (int)$product['id'] ?>" data-identifier="<?= $esc($product['imei'] ?? '') ?>" <?= (string)($device['camera_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · <?= $esc($product['imei'] ?? '') ?> · stock <?= (int)$product['opening_stock'] ?></option><?php endforeach; ?></select><input class="form-control mt-2" id="camera-identifier" value="<?= $esc($inventoryIdentifiers['camera']) ?>" placeholder="Camera serial from inventory" readonly><?php if (!$inventory['cameras']): ?><div class="form-text">No serialized cameras in stock.</div><?php endif; ?></div>
<div class="col-md-6"><label class="form-label" for="sim-product">Device SIM line <span class="text-secondary fw-normal">(optional)</span></label><select class="form-select install-sim" name="sim_product_id" id="sim-product"><option value="">No device SIM line</option><?php foreach ($inventory['sims'] as $product): ?><option value="<?= (int)$product['id'] ?>" data-sim-number="<?= $esc($product['imei'] ?? '') ?>" <?= (string)($device['sim_product_id'] ?? '') === (string)$product['id'] ? 'selected' : '' ?>><?= $esc($product['item_type']) ?> · <?= $esc($product['imei'] ?? '') ?></option><?php endforeach; ?></select></div>
