<div class="col-12 installation-form-section mt-2"><h2>Client and team</h2><p>Record the client and the staff responsible for the installation.</p></div>
<div class="col-md-4"><label class="form-label" for="client-id">Client</label><select class="form-select" name="client_id" id="client-id" required><option value="">Choose client</option><?php foreach ($clients as $client): ?><option value="<?= (int)$client['id'] ?>" <?= (string)($device['client_id'] ?? '') === (string)$client['id'] ? 'selected' : '' ?>><?= $esc($client['company_name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label" for="installer-id">Installer</label><select class="form-select" name="installer_id" id="installer-id" required><option value="">Choose installer</option><?php foreach ($users as $user): ?><option value="<?= (int)$user['id'] ?>" <?= (string)($device['installer_id'] ?? '') === (string)$user['id'] ? 'selected' : '' ?>><?= $esc($user['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label" for="support-id">IT support</label><select class="form-select" name="support_id" id="support-id" required><option value="">Choose IT support</option><?php foreach ($supportUsers as $user): ?><option value="<?= (int)$user['id'] ?>" <?= (string)($device['support_id'] ?? '') === (string)$user['id'] ? 'selected' : '' ?>><?= $esc($user['name']) ?></option><?php endforeach; ?></select></div>
