<div class="col-12 d-flex flex-wrap gap-2 pt-2"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk me-2"></i><?= $mode === 'edit' ? 'Update installation' : 'Save installation' ?></button><a class="btn btn-outline-secondary" href="/index.php?controller=gps">Cancel</a></div>
