<script>
const packageSelect=document.getElementById('package-type'),trackerSelect=document.getElementById('tracker-product'),trackerIdentifier=document.getElementById('tracker-identifier'),flsSelect=document.getElementById('fls-product'),cameraSelect=document.getElementById('camera-product'),simSelects=[...document.querySelectorAll('.install-sim')];
function fillIdentifier(select,target){const option=select.selectedOptions[0];document.getElementById(target).value=option?.dataset.identifier||'';}
function fillTrackerIdentifier(reset=false){const identifier=trackerSelect.selectedOptions[0]?.dataset.identifier||'',input=document.getElementById('tracker-identifier');input.readOnly=identifier!=='';if(identifier)input.value=identifier;else if(reset)input.value='';}
function syncSimLines(){const first=simSelects[0].value;[...simSelects[1].options].forEach(option=>{option.disabled=option.value!==''&&option.value===first;});if(simSelects[1].value===first)simSelects[1].value='';}
function syncPackage(){const cameraOnly=packageSelect.value==='Camera only',needsFls=['Basic + FLS','Basic + FLS + Camera'].includes(packageSelect.value),needsCamera=['Basic + FLS + Camera','Camera only','Camera + Basic'].includes(packageSelect.value);document.getElementById('tracker-product-field').classList.toggle('d-none',cameraOnly);document.getElementById('tracker-identifier-field').classList.toggle('d-none',cameraOnly);trackerSelect.disabled=cameraOnly;trackerSelect.required=!cameraOnly;trackerIdentifier.disabled=cameraOnly;trackerIdentifier.required=!cameraOnly;document.getElementById('fls-field').classList.toggle('d-none',!needsFls);document.getElementById('camera-field').classList.toggle('d-none',!needsCamera);flsSelect.disabled=!needsFls;flsSelect.required=needsFls;cameraSelect.disabled=!needsCamera;cameraSelect.required=needsCamera;if(!cameraOnly)fillTrackerIdentifier();else{trackerSelect.value='';trackerIdentifier.value='';}if(!needsFls)flsSelect.value='';if(!needsCamera)cameraSelect.value='';fillIdentifier(flsSelect,'fls-identifier');fillIdentifier(cameraSelect,'camera-identifier');}
packageSelect.addEventListener('change',syncPackage);trackerSelect.addEventListener('change',()=>fillTrackerIdentifier(true));flsSelect.addEventListener('change',()=>fillIdentifier(flsSelect,'fls-identifier'));cameraSelect.addEventListener('change',()=>fillIdentifier(cameraSelect,'camera-identifier'));simSelects.forEach(select=>select.addEventListener('change',syncSimLines));syncPackage();syncSimLines();
</script>
